package com.pp.shaderlod.optimization.photonearlyalpha.mixin;import com.mojang.blaze3d.opengl.GlProgram;import com.pp.shaderlod.optimization.photonearlyalpha.PhotonEarlyAlphaRuntime;import org.spongepowered.asm.mixin.*;import org.spongepowered.asm.mixin.injection.*;import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;@Mixin(value=GlProgram.class,remap=false)public abstract class PhotonAlphaProgramCloseMixin{@Shadow public abstract int getProgramId();@Inject(method="close()V",at=@At("HEAD"),require=1,allow=1)private void close(CallbackInfo c){PhotonEarlyAlphaRuntime.forgetDerived(getProgramId());}}
